#!/usr/bin/env python3
"""Extract first ~500 words from each file for classification."""

import os
import subprocess
import json

SRC = "/root/papers/all"

def extract_pdf_text(filepath, max_chars=3000):
    """Extract text from first page(s) of a PDF."""
    try:
        result = subprocess.run(
            ["pdftotext", "-l", "2", filepath, "-"],
            capture_output=True, text=True, timeout=15
        )
        return result.stdout[:max_chars]
    except Exception as e:
        return f"ERROR: {e}"

def extract_pptx_text(filepath, max_chars=3000):
    """Extract text from a PPTX file."""
    from pptx import Presentation
    try:
        prs = Presentation(filepath)
        texts = []
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, "text"):
                    texts.append(shape.text)
        return "\n".join(texts)[:max_chars]
    except Exception as e:
        return f"ERROR: {e}"

def extract_docx_text(filepath, max_chars=3000):
    """Extract text from a DOCX file."""
    from docx import Document
    try:
        doc = Document(filepath)
        texts = [p.text for p in doc.paragraphs]
        return "\n".join(texts)[:max_chars]
    except Exception as e:
        return f"ERROR: {e}"

results = {}
files = sorted(os.listdir(SRC))

for fname in files:
    fpath = os.path.join(SRC, fname)
    if fname.endswith(".pdf"):
        text = extract_pdf_text(fpath)
    elif fname.endswith(".pptx"):
        text = extract_pptx_text(fpath)
    elif fname.endswith(".docx"):
        text = extract_docx_text(fpath)
    else:
        text = "UNKNOWN FORMAT"
    results[fname] = text

# Output as JSON
with open("/root/extracted_texts.json", "w") as f:
    json.dump(results, f, indent=2)

print(f"Extracted text from {len(results)} files")
# Print first 200 chars of each for quick review
for fname, text in results.items():
    preview = text.replace("\n", " ")[:200]
    print(f"\n=== {fname} ===")
    print(preview)

